class Solution {
    public int[] singleNumber(int[] nums) {
        int x = 0;
        for (int v : nums) x ^= v;
        int diff = x & -x, a = 0;
        for (int v : nums) if ((v & diff) != 0) a ^= v;
        return new int[]{Math.min(a, x ^ a), Math.max(a, x ^ a)};
    }
}

